  const BLACK_KEY_OFFSETS = [1, 3, 6, 8, 10];
  function isBlackKey(midiNote) {
    return BLACK_KEY_OFFSETS.includes(midiNote % 12);
  }

  let whiteKeyCount = 0;
  for (let n = MIN_MIDI; n <= MAX_MIDI; n++) {
    if (!isBlackKey(n)) {
      whiteKeyCount++;
    }
  } // 52鍵

  const KEYBOARD_WIDTH = 312;
  const WHITE_KEY_WIDTH = KEYBOARD_WIDTH / whiteKeyCount; // 約 6.0px
  const midiToXMap = new Float32Array(128);

  let currentWhiteIdx = 0;
  for (let n = MIN_MIDI; n <= MAX_MIDI; n++) {
    if (!isBlackKey(n)) {
      midiToXMap[n] = -KEYBOARD_WIDTH / 2 + (currentWhiteIdx + 0.5) * WHITE_KEY_WIDTH;
      currentWhiteIdx++;
    } else {
      midiToXMap[n] = -KEYBOARD_WIDTH / 2 + currentWhiteIdx * WHITE_KEY_WIDTH;
    }
  }

