  let currentSoundType = 'bright'; // デフォルト：🌟 Bright Grand (煌びやかで抜けの良いブライトピアノ)
  let currentVisualMode = 'piano3d'; // デフォルト：✨ 3D Piano (88鍵 打鍵・ハンマー連動)

  let startTimeMs = -1;
