  // サンプルバッファ（FluidR3 & MusyngKite）
  const pianoSampleBuffers = {};
  const concertSampleBuffers = {};
  let isSoundfontLoading = false;
  let isSoundfontLoaded = false;
  let isConcertLoading = false;
  let isConcertLoaded = false;

  const NOTE_NAMES = ['C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab', 'A', 'Bb', 'B'];
  function midiToNoteName(midi) {
    const octave = Math.floor(midi / 12) - 1;
    const noteIndex = midi % 12;
    return NOTE_NAMES[noteIndex] + octave;
  }

  function noteNameToMidi(name) {
    const match = name.match(/^([A-G][b#]?)(-?\d+)$/);
    if (!match) return 60;
    const noteStr = match[1];
    const oct = parseInt(match[2], 10);
    const idx = NOTE_NAMES.indexOf(noteStr);
    if (idx < 0) return 60;
    return (oct + 1) * 12 + idx;
  }

  // 近傍サンプル検索＆ピッチシフト補間ヘルパー
  function findBestSample(sampleDict, targetMidi) {
    const targetName = midiToNoteName(targetMidi);
    if (sampleDict[targetName]) {
      return { buffer: sampleDict[targetName], playbackRate: 1.0 };
    }
    const keys = Object.keys(sampleDict);
    if (keys.length === 0) return null;

    let closestKey = null;
    let minDiff = 999;
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const m = noteNameToMidi(k);
      const diff = Math.abs(m - targetMidi);
      if (diff < minDiff) {
        minDiff = diff;
        closestKey = k;
      }
    }
    if (closestKey && minDiff <= 12) {
      const baseMidi = noteNameToMidi(closestKey);
      const semitones = targetMidi - baseMidi;
      return {
        buffer: sampleDict[closestKey],
        playbackRate: Math.pow(2, semitones / 12)
      };
    }
    return null;
  }

  // リアルなコンサートホールのインパルス応答生成（初期反射＋リッチな残響テイル）
  function createReverbImpulse(ctx) {
    const rate = ctx.sampleRate;
    const length = rate * 2.8; // 2.8秒の贅沢なコンサートホール残響
    const impulse = ctx.createBuffer(2, length, rate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
      const t = i / rate;
      // 複合減衰（初期反射の立ち上がり＋指数関数減衰）
      const early = (t < 0.08) ? (t / 0.08) * Math.sin(t * 800) * 0.4 : 0;
      const decay = Math.exp(-t * 2.6);
      const noiseL = (Math.random() * 2 - 1);
      const noiseR = (Math.random() * 2 - 1);
      left[i] = (noiseL * decay + early) * 0.7;
      right[i] = (noiseR * decay - early) * 0.7;
    }
    return impulse;
  }

  // 1. FluidR3 Standard Piano ロード
  function loadPianoSoundfont(ctx) {
    if (isSoundfontLoading || isSoundfontLoaded || typeof window === 'undefined') return;
    isSoundfontLoading = true;

    const script = document.createElement('script');
    script.src = 'https://gleitz.github.io/midi-js-soundfonts/FluidR3_GM/acoustic_grand_piano-mp3.js';
    script.async = true;
    script.onload = async () => {
      if (window.MIDI && window.MIDI.Soundfont && window.MIDI.Soundfont.acoustic_grand_piano) {
        const data = window.MIDI.Soundfont.acoustic_grand_piano;
        const keys = Object.keys(data);
        for (let i = 0; i < keys.length; i++) {
          const k = keys[i];
          const b64 = data[k];
          if (b64) {
            try {
              const bin = atob(b64.split(',')[1] || b64);
              const u8 = new Uint8Array(bin.length);
              for (let b = 0; b < bin.length; b++) u8[b] = bin.charCodeAt(b);
              pianoSampleBuffers[k] = await ctx.decodeAudioData(u8.buffer.slice(0));
            } catch (e) { }
          }
        }
        isSoundfontLoaded = true;
        console.log('FluidR3 Piano loaded! Keys:', Object.keys(pianoSampleBuffers).length);
      }
    };
    document.head.appendChild(script);
  }

